my $S='src/main/java/com/wormzjl/icheme/science/fluid/solver/SparseNewton.java';
open(F,'<:raw',$S) or die; my @l=<F>; close F; my $n=0;
for(@l){ if(s/catch\(SparseLuSolver\.SolveFailure failure\)\{workspace\.invalidate\(\);throw new Nonconvergence\("Singular Newton Jacobian: "\+failure\.getMessage\(\),x\);\}/catch(SparseLuSolver.SolveFailure failure){TraceDump.matrix(numeric);workspace.invalidate();throw new Nonconvergence("Singular Newton Jacobian: "+failure.getMessage(),x);}/){$n++} }
die "s$n" unless $n==1; open(F,'>:raw',$S) or die; print F @l; close F;
my $P='src/main/java/com/wormzjl/icheme/science/fluid/network/PassiveStepSolver.java';
open(F,'<:raw',$P) or die; @l=<F>; close F; $n=0; my @o;
my $d=q{if(dt<.002&&failure.getMessage().contains("Singular")){var tb=new StringBuilder("dt="+dt+" pass="+pass+" rate="+rateOnly+" modes="+modes+" closed="+Arrays.toString(boundaryClosed)+" phases="+Arrays.toString(phases)+" offsets="+Arrays.toString(equations.offsets)+" edgeOffset="+equations.edgeOffset+System.lineSeparator());for(var tp:graph.pipes())tb.append("pipe "+tp.first()+"->"+tp.second()+" "+tp.control()+System.lineSeparator());for(int ti=0;ti<seeds.size();ti++){var sd=seeds.get(ti);var in=inputStates.get(ti);var tn=graph.reservoirs().get(ti);tb.append("node "+ti+" id="+tn.id()+" "+tn.kind()+System.lineSeparator()+"  seed P="+sd.pressure()+" T="+sd.temperature()+" m="+sd.mass()+" vap="+sd.vaporVolume()+" liq="+sd.liquidVolume()+" wat="+sd.waterVolume()+" n="+Arrays.toString(PhaseLayout.totalAmounts(sd))+System.lineSeparator()+"  input P="+in.pressure()+" T="+in.temperature()+" m="+in.mass()+" vap="+in.vaporVolume()+" liq="+in.liquidVolume()+" n="+Arrays.toString(PhaseLayout.totalAmounts(in))+System.lineSeparator()+"  inventory="+Arrays.toString(tn.inventory().amounts())+" support="+Arrays.toString(supports[ti])+" reachable="+Arrays.toString(reachable[ti])+System.lineSeparator());}com.wormzjl.icheme.science.fluid.solver.TraceDump.write("nodes"+graph.reservoirs().stream().map(tr->tr.id()).toList(),tb.toString(),failure.lastVariables());}
};
for(@l){ if(/if\(changedSeeds==null\)throw new SparseNewton\.Nonconvergence\(failure\.getMessage\(\)\+"; active-set pass="\+pass/ && !$n){push @o,$d;$n++} push @o,$_; }
die "p$n" unless $n==1; open(F,'>:raw',$P) or die; print F @o; close F;
